={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const r = $json.row ?? $json;
  const t = (v) => String(v ?? '').trim();
  const allowed = String(S.allowed_currencies).split(',').map((x) => x.trim().toUpperCase());
  const moneyOk = (v) => /^-?\d+(\.\d{1,2})?$/.test(t(v));
  const dateOk = (v) => /^\d{4}-\d{2}-\d{2}$/.test(t(v)) && DateTime.fromISO(t(v), { zone: 'utc' }).isValid;
  const cur = t(r.currency).toUpperCase();
  let bad = '';
  if (t(r.line_id) === '') bad = 'missing_line_id';
  else if (!moneyOk(r.line_total)) bad = 'bad_money';
  else if (!dateOk(r.sale_date)) bad = 'bad_date';
  else if (!allowed.includes(cur)) bad = 'bad_currency';
  return {
    line_id: t(r.line_id), sale_date: t(r.sale_date), currency: cur,
    customer_key: t(r.customer_name).replace(/\s+/g, ' '),
    line_total_minor: moneyOk(r.line_total) ? Math.round(Number(t(r.line_total)) * 100) : 0,
    bad_reason: bad, row_valid: bad === ''
  };
})()) }}

={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const r = $json.row ?? $json;
  const t = (v) => String(v ?? '').trim();
  const allowed = String(S.allowed_currencies).split(',').map((x) => x.trim().toUpperCase());
  const moneyOk = (v) => /^-?\d+(\.\d{1,2})?$/.test(t(v));
  const dateOk = (v) => /^\d{4}-\d{2}-\d{2}$/.test(t(v)) && DateTime.fromISO(t(v), { zone: 'utc' }).isValid;
  const minor = (v) => moneyOk(v) ? Math.round(Number(t(v)) * 100) : 0;
  const inv = t(r.invoice_no);
  const cur = t(r.currency).toUpperCase();
  const docType = t(r.doc_type).toLowerCase();
  const status = t(r.status).toLowerCase();
  const dup = $('Split invoices').all().filter((x) => t((x.json.row ?? x.json).invoice_no) === inv).length > 1;
  const am = minor(r.amount);
  const pm = minor(r.amount_paid);
  const bm = minor(r.balance);
  let bad = '';
  if (inv === '') bad = 'missing_invoice_no';
  else if (dup) bad = 'duplicate_invoice_no';
  else if (!moneyOk(r.amount) || !moneyOk(r.amount_paid) || !moneyOk(r.balance)) bad = 'bad_money';
  else if (!dateOk(r.issue_date) || !dateOk(r.due_date) || (t(r.paid_date) !== '' && !dateOk(r.paid_date))) bad = 'bad_date';
  else if (!allowed.includes(cur)) bad = 'bad_currency';
  else if (!['invoice', 'credit_note'].includes(docType) || !['open', 'paid', 'void'].includes(status)) bad = 'bad_type_or_status';
  else if (status !== 'void' && bm !== am - pm) bad = 'balance_mismatch';
  else if (docType === 'invoice' && bm < 0) bad = 'negative_balance';
  return {
    invoice_no: inv, doc_type: docType, status: status,
    customer_name: t(r.customer_name).replace(/\s+/g, ' '), customer_email: t(r.customer_email),
    issue_date: t(r.issue_date), due_date: t(r.due_date), paid_date: t(r.paid_date), currency: cur,
    amount_minor: am, paid_minor: pm, balance_minor: bm,
    email_usable: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t(r.customer_email)),
    bad_reason: bad, row_valid: bad === ''
  };
})()) }}

={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const wk = $('Work out report week').first().json;
  const c = String($json.currency);
  const tol = Number(S.control_tolerance_minor);
  const t = (v) => String(v ?? '').trim();
  const sales = $('Pack sales figures').first().json.sales_rows || [];
  const age = $('Pack ageing figures').first().json.ageing_rows || [];
  const custs = $('Pack customers').first().json.customers || [];
  const prevAll = $('Pack last week report').first().json.rows || [];
  const cs = $('Pack control sales').first().json.rows || [];
  const co = $('Pack control open').first().json.rows || [];
  const sv = (b) => { const r = sales.find((x) => x.currency === c && x.bucket === b); return r ? Number(r.sales_minor) : 0; };
  const sc = (b) => { const r = sales.find((x) => x.currency === c && x.bucket === b); return r ? Number(r.sales_count) : 0; };
  const ab = (b) => { const r = age.find((x) => x.currency === c && x.bucket === b); return r ? Number(r.bal_minor) : 0; };
  const ac = (b) => { const r = age.find((x) => x.currency === c && x.bucket === b); return r ? Number(r.cnt) : 0; };
  const salesMinor = sv('current'); const salesCount = sc('current'); const priorMinor = sv('prior'); const priorCount = sc('prior');
  const openMinor = ab('not_due') + ab('d1_7') + ab('d8_30') + ab('d31_plus');
  const openCount = ac('not_due') + ac('d1_7') + ac('d8_30') + ac('d31_plus');
  const overdueMinor = ab('d1_7') + ab('d8_30') + ab('d31_plus');
  const overdueCount = ac('d1_7') + ac('d8_30') + ac('d31_plus');
  const noEmail = $('Work out ageing').isExecuted ? $('Work out ageing').all().filter((i) => i.json.currency === c && i.json.days_past_due >= 1 && i.json.email_usable === false).length : 0;
  const numOk = (v) => /^-?\d+(\.\d{1,2})?$/.test(t(v));
  const num = (v) => numOk(v) ? Math.round(Number(t(v)) * 100) : null;
  const cnt = (v) => /^\d+$/.test(t(v)) ? Number(t(v)) : null;
  const fails = [];
  const chk = (metric, mine, theirs) => { if (theirs === null) fails.push(c + ', ' + metric + ' (control value unreadable)'); else if (Math.abs(mine - theirs) > tol) fails.push(c + ', ' + metric + ' (difference ' + (mine - theirs) + ' minor units)'); };
  const chkc = (metric, mine, theirs) => { if (theirs === null) fails.push(c + ', ' + metric + ' (control value unreadable)'); else if (mine !== theirs) fails.push(c + ', ' + metric + ' (difference ' + (mine - theirs) + ')'); };
  const cur = cs.filter((x) => t(x.week_start) === wk.week_start && t(x.currency).toUpperCase() === c);
  const pri = cs.filter((x) => t(x.week_start) === wk.prior_week_start && t(x.currency).toUpperCase() === c);
  const opn = co.filter((x) => t(x.currency).toUpperCase() === c);
  if (cur.length !== 1) fails.push(c + ', control_sales_week row for the report week (found ' + cur.length + ')'); else { chk('sales_total', salesMinor, num(cur[0].sales_total)); chkc('sales_line_count', salesCount, cnt(cur[0].sales_line_count)); }
  if (pri.length !== 1) fails.push(c + ', control_sales_week row for the prior week (found ' + pri.length + ')'); else { chk('prior_sales_total', priorMinor, num(pri[0].sales_total)); chkc('prior_sales_line_count', priorCount, cnt(pri[0].sales_line_count)); }
  if (opn.length !== 1) fails.push(c + ', control_open row (found ' + opn.length + ')'); else { chk('open_balance', openMinor, num(opn[0].open_balance_total)); chkc('open_invoice_count', openCount, cnt(opn[0].open_invoice_count)); }
  const prev = prevAll.find((x) => t(x.currency).toUpperCase() === c);
  const prevOverdue = prev && numOk(prev.overdue_balance) ? num(prev.overdue_balance) : null;
  const prevCount = prev && cnt(prev.overdue_count) !== null ? cnt(prev.overdue_count) : null;
  const dirPct = (a, b) => { if (b === 0) return a === 0 ? 'flat' : ''; const p = (a - b) / Math.abs(b) * 100; return Math.abs(p) < 1 ? 'flat' : (p > 0 ? 'up' : 'down'); };
  const band = (a, b) => { if (b === 0) return 'small'; const p = Math.abs((a - b) / b * 100); return p < 5 ? 'small' : (p < 20 ? 'moderate' : 'large'); };
  const offered = [];
  const dSales = dirPct(salesMinor, priorMinor);
  if (dSales !== '') offered.push({ currency: c, metric_key: 'sales', direction: dSales, band: band(salesMinor, priorMinor) });
  if (prevOverdue !== null) { const d = dirPct(overdueMinor, prevOverdue); if (d !== '') offered.push({ currency: c, metric_key: 'overdue_amount', direction: d, band: band(overdueMinor, prevOverdue) }); }
  if (prevCount !== null) { const dd = overdueCount - prevCount; offered.push({ currency: c, metric_key: 'overdue_count', direction: dd === 0 ? 'flat' : (dd > 0 ? 'up' : 'down'), band: Math.abs(dd) <= 2 ? 'small' : (Math.abs(dd) <= 5 ? 'moderate' : 'large') }); }
  const top = custs.filter((x) => t(x.currency) === c).slice(0, Number(S.top_n)).map((x, i) => ({ rank: i + 1, customer_name: t(x.customer_key), sales_minor: Number(x.sum_line_total_minor) }));
  return {
    currency: c, week_start: wk.week_start, week_end: wk.week_end,
    sales_minor: salesMinor, sales_count: salesCount, prior_sales_minor: priorMinor, prior_sales_count: priorCount,
    change_abs_minor: salesMinor - priorMinor, change_pct: priorMinor === 0 ? 'n/a' : ((salesMinor - priorMinor) / priorMinor * 100).toFixed(1),
    open_minor: openMinor, open_count: openCount, overdue_minor: overdueMinor, overdue_count: overdueCount,
    age_not_due_minor: ab('not_due'), age_1_7_minor: ab('d1_7'), age_8_30_minor: ab('d8_30'), age_31_plus_minor: ab('d31_plus'),
    overdue_no_email_count: noEmail, control_failures: fails, offered: offered,
    top: top.length ? top : [{ rank: 0, customer_name: '(no sales)', sales_minor: 0 }]
  };
})()) }}

={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const t = (v) => String(v ?? '').trim();
  const allowed = String(S.allowed_currencies).split(',').map((x) => x.trim().toUpperCase());
  const wk = $('Work out report week').first().json;
  const figs = $json.figures;
  const nb = (rows) => rows.filter((r) => Object.values(r.json.row ?? r.json).some((v) => String(v ?? '').trim() !== ''));
  const invRead = nb($('Split invoices').all()).length;
  const invValid = $('Check invoice row').all().filter((i) => i.json.row_valid === true).length;
  const salRead = nb($('Split sales lines').all()).length;
  const salValid = $('Check sales line').all().filter((i) => i.json.row_valid === true).length;
  const fails = figs.flatMap((f) => f.control_failures);
  if (invRead !== invValid) fails.push('invoices, rows_read vs rows_valid (read ' + invRead + ', valid ' + invValid + ')');
  if (salRead !== salValid) fails.push('sales_lines, rows_read vs rows_valid (read ' + salRead + ', valid ' + salValid + ')');
  const csRows = $('Pack control sales').first().json.rows || [];
  const coRows = $('Pack control open').first().json.rows || [];
  if (csRows.some((x) => t(x.currency) !== '' && !allowed.includes(t(x.currency).toUpperCase()))) fails.push('control_sales_week, currency not in the allowed list');
  if (coRows.some((x) => t(x.currency) !== '' && !allowed.includes(t(x.currency).toUpperCase()))) fails.push('control_open, currency not in the allowed list');
  return { figures: figs, control_ok: fails.length === 0, control_failures: fails, first_failure: fails[0] || '', control_detail: fails.join('; ').slice(0, 480), rows_read: invRead + salRead, rows_valid: invValid + salValid };
})()) }}

