={{ (() => {
  const S = $('Settings').first().json;
  const o = $json.output;
  const offered = $('Prepare aggregates for AI').first().json.offered;
  const thr = Number(S.confidence_threshold);
  const banned = /\b(doubl\w*|tripl\w*|twice|half|halv\w*|third\w*|quarter\w*|percent\w*|thousand\w*|million\w*)\b/i;
  const txtOk = (x) => typeof x === 'string' && x.length >= 1 && x.length <= 160 && !/\p{Nd}/u.test(x) && /^\p{L}[\p{L} .,'\-:;()]*$/u.test(x) && !banned.test(x);
  if (!o || typeof o !== 'object' || Array.isArray(o)) return 'format';
  if (Object.keys(o).sort().join(',') !== 'confidence,headline,items,reason') return 'format';
  if (!txtOk(o.headline) || !txtOk(o.reason)) return 'text';
  if (!Array.isArray(o.items) || o.items.length < 1 || o.items.length > 4) return 'format';
  const seen = new Set();
  for (const it of o.items) {
    if (!it || typeof it !== 'object' || Object.keys(it).sort().join(',') !== 'currency,direction,metric_key,note') return 'format';
    if (!txtOk(it.note)) return 'text';
    const k = it.currency + '|' + it.metric_key;
    if (seen.has(k)) return 'pair';
    seen.add(k);
    const off = offered.find((x) => x.currency === it.currency && x.metric_key === it.metric_key);
    if (!off) return 'pair';
    if (it.direction !== off.direction) return 'direction';
  }
  if (typeof o.confidence !== 'number' || !(o.confidence >= 0 && o.confidence <= 1)) return 'format';
  if (o.confidence < thr) return 'confidence';
  return '';
})() }}

