parameters.message:
={{ (() => {
  const nl = String.fromCharCode(10);
  const S = $('Settings').first().json;
  const f = $('Compare with control totals').first().json.figures;
  const cm = $('Set commentary text').first().json;
  const m = (v) => (v / 100).toFixed(2);
  const L = ['Weekly invoice report: ' + f[0].week_start + ' to ' + f[0].week_end, 'The sales and open-balance totals were checked against the control tabs and matched.', ''];
  for (const x of f) {
    L.push(x.currency);
    L.push('  Sales: ' + m(x.sales_minor) + ' (' + x.sales_count + ' lines)');
    L.push('  Change vs last week: ' + (x.change_abs_minor >= 0 ? '+' : '') + m(x.change_abs_minor) + ' (' + (x.change_pct === 'n/a' ? 'n/a' : x.change_pct + '%') + ')');
    L.push('  Open balance: ' + m(x.open_minor) + ' (' + x.open_count + ' invoices)');
    L.push('  Overdue: ' + m(x.overdue_minor) + ' (' + x.overdue_count + ' invoices); ' + x.overdue_no_email_count + ' overdue with no usable email');
    L.push('  Top customers:');
    for (const t of x.top) L.push('    ' + (t.rank === 0 ? '' : t.rank + '. ') + t.customer_name + (t.rank === 0 ? '' : ': ' + m(t.sales_minor)));
    L.push('');
  }
  L.push(cm.commentary_status === 'ok' ? 'AI-written commentary (not checked against your books):' + nl + cm.commentary_text : 'AI commentary not available this week');
  L.push('');
  L.push('Sheet: ' + S.sheet_url);
  return L.join(nl);
})() }}

